#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
Compile a physical 1-D model + the LAN WLED's ring geometry into a WLED
playlist of authored key frames ("按物理规律生成关键帧动画").

Why this exists
---------------
`references/recipe-design-methodology.md` mandates this order:
   S1 find a real reference  ->  S2 space structure + first/last frame
   -> S3 speed from physics  ->  S4 four-edge layout for the actual ring
   -> S5 read the FX source  ->  S6 probe  ->  S7 save/verify/restore

Steps S2-S4 are what this script does. It is deliberately NOT "pick an effect
whose name sounds like the thing":

  * Speed is a *result of the timing*, not a slider guess. One frame advances the
    wave front by a fixed fraction of the ring, and WLED is told `transition ==
    dur`, so every frame is one continuous crossfade into the next
    (playlist.cpp: `strip.setTransition(entries[i].tr * 100)` then
    `playlistEntryDur = entries[i].dur`; there is no clamp forcing tr <= dur).
    px/s = ring_leds * step_per_frame / frame_seconds -- deterministic, and the
    physics table below says what that number must be.

  * The picture is a *distance field*, not four unrelated edge effects. A wave on
    a TV bezel does not orbit: it starts at the horizon (the far edge), runs down
    BOTH side edges at once (mirror symmetric, the WLED docs' own recipe:
    "divide your strip into two segments, reverse the second one"), and lands on
    the shore (the near edge). `d(s)` below is 0 at the far-edge centre and 1 at
    the near-edge centre, so a front at phase p is the set of ring positions with
    d == p -- a symmetric PAIR of fronts, never a lap.

  * Every LED is lit at every moment (20-28 Solid bands tile the whole strip), so
    the "只有一小段" failure cannot happen, and no band is ever black.

Physics table (why the default numbers are what they are)
--------------------------------------------------------
    wind swell period on a beach        8-14 s      -> default 12 s
    one crest horizon -> shore          ~ one period (calm, "one wave at a time")
    frames per cycle                    8 (6 advancing + 2 lull)
    frame seconds = period / frames_per_cycle                        = 1.5 s
    lull                                2 frames with the front held at the horizon
                                        ("一组浪之间的间歇"); the foam of the wave
                                        that just broke is still on the sand
    ring travel per frame = 1 / advancing frames of the distance field
    front speed = ring_leds / period  [LED/s]
        e.g. 70 LEDs / 12 s = 5.8 LED/s = 一圈 12 s
    Deliberately slow: the rejected recipe moved ~7x faster than this.
    One crest only. With 2 identical crests the field repeats every period/2, so
    the *visual* period silently halves (measured: 6 s repeat for a stated 12 s) —
    faster than a real swell, which is exactly the "太快" complaint.

Usage:
    python3 scripts/build_keyframe_animation.py                      # 海浪拍打沙滩
    python3 scripts/build_keyframe_animation.py --period 12 --cycles 5
    python3 scripts/build_keyframe_animation.py --print-frames        # 只看关键帧表
    python3 scripts/build_keyframe_animation.py --out recipes/xxx.json
"""
import json
import math
import os
import sys

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
SKILL_DIR = os.path.dirname(SCRIPT_DIR)
sys.path.insert(0, SCRIPT_DIR)

# --- palette: a real sea, sampled from the reference photos -----------------
DEEP = (14, 92, 130)        # 远处深海
MID = (23, 137, 200)        # 中层海水
SHALLOW = (47, 182, 216)    # 近岸浅水
WASH = (127, 227, 238)      # 浪过之后翻涌的白绿水
FOAM = (234, 251, 255)      # 浪花
SAND = (239, 199, 126)      # 沙滩
WET_SAND = (201, 154, 87)   # 湿沙

PHYSICAL_PERIOD_S = 12.0    # 真实涌浪周期（记录在案的 8-14s 区间内偏慢）


def _clamp01(x):
    return 0.0 if x < 0.0 else (1.0 if x > 1.0 else x)


def _smoothstep(edge0, edge1, x):
    if edge1 == edge0:
        return 0.0
    t = _clamp01((x - edge0) / (edge1 - edge0))
    return t * t * (3.0 - 2.0 * t)


def _mix(a, b, t):
    t = _clamp01(t)
    return tuple(int(round(a[i] + (b[i] - a[i]) * t)) for i in range(3))


def _lerp3(a, b, c, t):
    """Piecewise a->b->c, used for the bathymetry (deep -> mid -> shallow)."""
    return _mix(a, b, t * 2.0) if t < 0.5 else _mix(b, c, (t - 0.5) * 2.0)


# --- the model ------------------------------------------------------------
def sea_colour(d, phase, profile):
    """Colour at normalised distance `d` from the horizon when the front is at `phase`.

    d = 0 horizon (far edge centre) ... d = 1 shore (near edge centre).

    `crests` is 1 by default on purpose: with 2 identical crests spaced 1/2 apart
    the field repeats when the phase advances by 0.5, so the *visual* period is
    half of `period` — measured as a 6 s repeat when the stated period was 12 s,
    i.e. faster than a real swell. One crest makes `period` mean what it says.
    Structure instead comes from depth layering + wash + shore foam.
    """
    crests = profile["crests"]
    shore_d = profile["shore_d"]

    # 1) 海床的固定层次：越靠岸越浅
    base = _lerp3(DEEP, MID, SHALLOW, _smoothstep(0.0, 1.0, d))

    # 2) 浪花与「浪过之后翻涌的水」
    foam_amt = 0.0
    lag_amt = 0.0
    swash_amt = 0.0
    for k in range(crests):
        ck = (phase + k / float(crests)) % 1.0
        amp = 1.0 - profile["break_fade"] * _smoothstep(0.70, 1.0, ck)  # 进浅水就碎
        foam_amt = max(foam_amt, amp * math.exp(-((d - ck) / profile["crest_width"]) ** 2))
        if d <= ck:  # 这道浪已经过去了
            lag_amt = max(lag_amt, math.exp(-(ck - d) / profile["wash_len"]))
        # 3) 岸边白沫：浪冲上沙滩后先铺开、再滞留、最后退去。
        #    t_since 从 0 开始增长，所以浪碎在岸边（ck≈0.9）时白沫最盛，
        #    之后的静涌帧里白沫仍在缓慢消退——这就是「一浪推上来又退回去」。
        t_since = (ck - shore_d) % 1.0
        swash_amt = max(swash_amt, math.exp(-t_since / profile["swash_life"]))
    swash = swash_amt * _smoothstep(0.72, 1.0, d)

    col = base
    col = _mix(col, WASH, profile["wash_bright"] * lag_amt)
    # 水线是一条硬边界：过渡带窄一点，否则蓝色和沙色各占一半会混成脏绿
    col = _mix(col, SAND if d > 0.975 else WET_SAND,
               _smoothstep(0.930, 0.995, d) * (1.0 - 0.85 * swash))
    col = _mix(col, FOAM, profile["foam_bright"] * foam_amt)
    col = _mix(col, FOAM, 0.88 * swash)
    return col


# --- ring geometry --------------------------------------------------------
def edge_order(layout):
    """Same order _build_tv_segments uses, so bands tile the strip 0..N."""
    top = int(layout["edges"].get("top", 0))
    right = int(layout["edges"].get("right", 0))
    bottom = int(layout["edges"].get("bottom", 0))
    left = int(layout["edges"].get("left", 0))
    direction = layout.get("direction", "cw")
    start = layout.get("start_corner", "top_left")
    if direction == "cw":
        table = {
            "top_left": [("top", top), ("right", right), ("bottom", bottom), ("left", left)],
            "top_right": [("right", right), ("bottom", bottom), ("left", left), ("top", top)],
            "bottom_right": [("bottom", bottom), ("left", left), ("top", top), ("right", right)],
            "bottom_left": [("left", left), ("top", top), ("right", right), ("bottom", bottom)],
        }
    else:
        table = {
            "top_left": [("left", left), ("bottom", bottom), ("right", right), ("top", top)],
        }
    return table.get(start, [("top", top), ("right", right), ("bottom", bottom), ("left", left)])


def ring_geometry(total_leds, layout, bands):
    """Split the strip into `bands` contiguous chunks and give each its distance d.

    Returns [(start, stop, d), ...] where d=0 is the horizon (centre of the far
    edge) and d=1 is the shore (centre of the near edge). The far edge is the one
    named "top" in the layout — on a TV backlight that is the horizon.
    """
    edges = edge_order(layout)
    counted = [(n, ln) for n, ln in edges if ln > 0]
    if counted and sum(ln for _, ln in counted) == total_leds:
        seq = counted
    else:
        # linear / no usable edge config -> treat the strip as one ring
        seq = [("top", total_leds // 2), ("bottom", total_leds - total_leds // 2)]

    # centre of the first edge ("top" = far edge) in ring-fraction coordinates
    far_centre = (seq[0][1] / 2.0) / float(total_leds)

    out = []
    bounds = [int(round(i * total_leds / float(bands))) for i in range(bands + 1)]
    for i in range(bands):
        start, stop = bounds[i], bounds[i + 1]
        if stop <= start:
            continue
        s = ((start + stop) / 2.0) / float(total_leds)
        delta = abs(s - far_centre)
        d = min(delta, 1.0 - delta) / 0.5
        out.append((start, stop, _clamp01(d)))
    return out


# --- frame compiler -------------------------------------------------------
def build_recipe(config, period=PHYSICAL_PERIOD_S, frames_per_cycle=8, cycles=5,
                 bands=28, bri=220, preset_base=110, playlist_preset_id=150,
                 name="海浪拍打沙滩", lull_frames=0, crests=1):
    """Compile the model into a playlist recipe.

    Phase advances uniformly, one full distance-field crossing per `period`.
    `lull_frames` (default 0) inserts extra frames holding the front at the
    horizon for "一组浪之间的间歇" — be careful: those frames are IDENTICAL, so
    with `transition == dur` they read as a frozen strip. Only use it if that
    pause is wanted, and keep it to one frame.
    """
    total = int((config.get("layout") or {}).get("total_leds") or 0)
    if total <= 0:
        raise SystemExit("config.json 缺少 layout.total_leds")
    layout = config["layout"]
    geom = ring_geometry(total, layout, bands)
    if not geom:
        raise SystemExit("无法从 layout 推导环上分带，请检查 config.json 的 layout.edges")

    crossing = max(1, frames_per_cycle - lull_frames)
    phase_table = [i / float(crossing) for i in range(crossing)] + [0.0] * lull_frames

    frame_s = period / float(frames_per_cycle)
    dur_tenths = int(round(frame_s * 10))
    total_frames = frames_per_cycle * cycles

    scenes = []
    for f in range(total_frames):
        cycle, step = divmod(f, frames_per_cycle)
        phase = phase_table[step]
        # 每一轮轻微变化：浪的厚薄与翻涌亮度不同，避免 60 秒听成同一段复制
        var = math.sin(2.0 * math.pi * cycle / max(1, cycles))
        profile = {
            "crests": crests,
            "crest_width": 0.12 * (1.0 + 0.15 * var),
            "wash_len": 0.20,
            "wash_bright": 0.68 * (1.0 + 0.12 * var),
            "foam_bright": 0.92,
            "break_fade": 0.55,
            "shore_d": 0.90,
            "swash_life": 0.10,
        }
        frame_bands = [tuple([start, stop] + list(sea_colour(d, phase, profile)))
                       for start, stop, d in geom]
        scenes.append({
            "name": f"第{cycle + 1}组·{step + 1}/{frames_per_cycle}",
            "duration": dur_tenths,
            "bri": bri,
            "bands": frame_bands,
        })

    return {
        "name": name,
        "type": "playlist",
        "bri": bri,
        "preset_base": preset_base,
        "playlist_preset_id": playlist_preset_id,
        "loop": {"repeat": 0, "transition": [dur_tenths] * len(scenes)},
        "_design": {
            "reference": "真实海滩照片：远处海平线 -> 深蓝浪面 -> 白色浪花带 -> 前景沙滩",
            "space": ("按环形距离场 d 分带：d=0 在最远端（top 边中心），d=1 在最近端"
                      "（bottom 边中心）。波前在 d=phase，因此同一时刻左右两侧各有一个对称"
                      "波前同时向岸边推进——不是绕圈，是浪从远处推过来。"),
            "physics": (f"真实涌浪周期 {period:.1f}s，每周期 {frames_per_cycle} 帧"
                        f"（{crossing} 帧推浪 + {lull_frames} 帧间歇）、每帧 {frame_s:.1f}s，"
                        f"transition == dur 使帧间连续交叉淡入；波前速度 = "
                        f"{total} / {period:.1f} = {total / period:.1f} LED/s。"),
            "coverage": f"{bands} 个 Solid 段首尾相连铺满 {total} 颗灯珠，任一时刻无黑段。",
            "loop_seconds": round(total_frames * frame_s, 1),
        },
        "scenes": scenes,
        "stop": {"on": False},
    }


def compact_recipe(recipe, model):
    """The on-disk form: model parameters + design notes, no expanded frames.

    A 40-frame x 28-band animation is ~30 KB of numbers however it is written.
    Storing the *model* instead keeps the recipe ~2 KB, human-readable, diffable
    and tweakable (`period`, `frames_per_cycle`, `cycles`), and the frames are
    compiled at apply time by apply_recipe.py. The physics table above is the
    contract: change `period` and the speed changes exactly as documented.
    """
    out = {k: v for k, v in recipe.items() if k != "scenes"}
    # one scalar instead of a 40-entry list when every frame uses the same crossfade
    loop = dict(out.get("loop") or {})
    tr = loop.get("transition")
    if isinstance(tr, (list, tuple)) and tr and len(set(tr)) == 1:
        loop["transition"] = tr[0]
    out["loop"] = loop
    out["model"] = dict(model)
    out["_design"]["key_frames"] = (f"由 scripts/build_keyframe_animation.py 编译："
                                    f"{model['cycles']} 组 × {model['frames_per_cycle']} 帧，"
                                    f"每帧 {model['bands']} 个 Solid 段。"
                                    f"用 --print-frames 查看沿环色带。")
    return out


def main():
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__)
        sys.exit(0)

    def opt(flag, default, cast=str):
        if flag in sys.argv:
            return cast(sys.argv[sys.argv.index(flag) + 1])
        return default

    from apply_recipe import load_config
    config = load_config()

    period = opt("--period", PHYSICAL_PERIOD_S, float)
    frames_per_cycle = opt("--frames-per-cycle", 8, int)
    cycles = opt("--cycles", 5, int)
    bands = opt("--bands", 28, int)
    bri = opt("--bri", 220, int)
    lull_frames = opt("--lull", 0, int)
    crests = opt("--crests", 1, int)
    preset_base = opt("--preset-base", 110, int)
    playlist_preset_id = opt("--playlist-preset", 150, int)
    name = opt("--name", "海浪拍打沙滩")
    out = opt("--out", os.path.join(SKILL_DIR, "recipes", f"{name}.json"))

    model = {"kind": "sea_wave", "period": period, "frames_per_cycle": frames_per_cycle,
             "cycles": cycles, "bands": bands, "crests": crests, "lull_frames": lull_frames,
             "bri": bri, "preset_base": preset_base,
             "playlist_preset_id": playlist_preset_id}
    recipe = build_recipe(
        config, period=period, frames_per_cycle=frames_per_cycle, cycles=cycles,
        bands=bands, bri=bri, preset_base=preset_base,
        playlist_preset_id=playlist_preset_id, name=name,
        lull_frames=lull_frames, crests=crests)

    d = recipe["_design"]
    print(f"名称: {recipe['name']}")
    print(f"关键帧: {len(recipe['scenes'])} 帧 × {recipe['scenes'][0]['duration'] / 10.0:.1f}s "
          f"= {d['loop_seconds']:.0f}s 一轮（repeat=0 无限循环）")
    print(f"每帧分段: {len(recipe['scenes'][0]['bands'])} 个 Solid 段")
    print(f"物理: {d['physics']}")
    print(f"空间: {d['space']}")
    print(f"覆盖: {d['coverage']}")

    if "--print-frames" in sys.argv:
        show = min(len(recipe["scenes"]), frames_per_cycle)
        print(f"\n前 {show} 帧（一个完整周期）的沿环色带，[ ] 标记波前所在段:")
        for i in range(show):
            sc = recipe["scenes"][i]
            bands = sc["bands"]
            cols = [f"#{b[2]:02X}{b[3]:02X}{b[4]:02X}" for b in bands]
            idx = max(range(len(bands)), key=lambda j: sum(bands[j][2:5]))
            cols[idx] = f"[{cols[idx]}]"
            print(f"帧 {i:>2} φ={((i % frames_per_cycle) / float(frames_per_cycle)):.3f}  "
                  + " ".join(cols))
        print()
    if "--dry-run" in sys.argv or "--print-frames" in sys.argv:
        return

    payload = recipe if "--expand" in sys.argv else compact_recipe(recipe, model)
    with open(out, "w", encoding="utf-8") as fh:
        json.dump(payload, fh, indent=2, ensure_ascii=False)
        fh.write("\n")
    print(f"\n已写出: {out}  ({os.path.getsize(out)} bytes"
          f"{'，含展开关键帧' if '--expand' in sys.argv else '，仅模型参数（apply 时编译）'})")


if __name__ == "__main__":
    main()
